#!/bin/bash
# Uninstall script for Waterfox
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Waterfox..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Waterfox if running..."
pkill -f "Waterfox" 2>/dev/null || true

# Remove /Applications/Waterfox.app
echo "Removing /Applications/Waterfox.app..."
if [ -d "/Applications/Waterfox.app" ]; then
    rm -rf "/Applications/Waterfox.app" 2>/dev/null || true
elif [ -f "/Applications/Waterfox.app" ]; then
    rm -f "/Applications/Waterfox.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.waterfox.sfl*
echo "Removing $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.waterfox.sfl*..."
if [ -d "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.waterfox.sfl*" ]; then
    rm -rf "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.waterfox.sfl*" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.waterfox.sfl*" ]; then
    rm -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.waterfox.sfl*" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Waterfox
echo "Removing $HOME/Library/Application Support/Waterfox..."
if [ -d "$HOME/Library/Application Support/Waterfox" ]; then
    rm -rf "$HOME/Library/Application Support/Waterfox" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Waterfox" ]; then
    rm -f "$HOME/Library/Application Support/Waterfox" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/Waterfox
echo "Removing $HOME/Library/Caches/Waterfox..."
if [ -d "$HOME/Library/Caches/Waterfox" ]; then
    rm -rf "$HOME/Library/Caches/Waterfox" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/Waterfox" ]; then
    rm -f "$HOME/Library/Caches/Waterfox" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/org.waterfoxproject.waterfox.plist
echo "Removing $HOME/Library/Preferences/org.waterfoxproject.waterfox.plist..."
if [ -d "$HOME/Library/Preferences/org.waterfoxproject.waterfox.plist" ]; then
    rm -rf "$HOME/Library/Preferences/org.waterfoxproject.waterfox.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/org.waterfoxproject.waterfox.plist" ]; then
    rm -f "$HOME/Library/Preferences/org.waterfoxproject.waterfox.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
